{"command":"$lines = Get-Content .\input\session.jsonl -Encoding UTF8
$out = foreach($l in $lines){
  try {
    $o = $l | ConvertFrom-Json
    $p = $o.payload
    $kind = $p.type
    $role = ''
    $text = ''
    if($o.type -eq 'response_item' -and $p.type -eq 'message'){ $role = $p.role }
    if($p.type -eq 'event_msg'){ }
    [pscustomobject]@{ ordinal=$o.ordinal; otype=$o.type; ptype=$p.type; role=$role }
  } catch {
    [pscustomobject]@{ ordinal='?'; otype='PARSE_FAIL'; ptype=''; role='' }
  }
}
$out | Format-Table -AutoSize | Out-String -Width 200"}

{"command":"$lines = Get-Content .\input\session.jsonl -Encoding UTF8
foreach($l in $lines){
  try {
    $o = $l | ConvertFrom-Json
    if($o.type -eq 'response_item'){
      $p = $o.payload
      if($p.type -eq 'message' -and ($p.role -eq 'user' -or $p.role -eq 'assistant')){
        $txt = ($p.content | ForEach-Object { if($_.text){$_.text}elseif($_.Text){$_.Text} }) -join "`n"
        Write-Output ("=====ORDINAL " + $o.ordinal + " ROLE " + $p.role + "=====")
        Write-Output $txt
        Write-Output ""
      }
    }
  } catch {}
}"}

