{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$lines = Get-Content .\input\session.jsonl -Encoding UTF8
foreach($l in $lines){
  try {
    $o = $l | ConvertFrom-Json
    $p = $o.payload
    if($o.type -eq 'response_item' -and $p.type -eq 'custom_tool_call'){
      Write-Output ("TOOLCALL ord " + $o.ordinal + " name=" + $p.name + " call=" + $p.call_id)
      $inp = $p.input
      $s = $inp | ConvertTo-Json -Depth 6 -Compress
      if($s.Length -gt 400){ $s = $s.Substring(0,400) + '...TRUNC' }
      Write-Output ("   input: " + $s)
    }
    if($o.type -eq 'event_msg' -and $p.type -eq 'item_completed'){
      $item = $p.item
      if($item.type -eq 'CommandExecution'){
        $cmd = ($item.command -join ' ')
        if($cmd.Length -gt 500){ $cmd = $cmd.Substring(0,500) + '...TRUNC' }
        Write-Output ("CMDEXEC ord " + $o.ordinal + " status=" + $item.status + " exit=" + $item.exit_code)
        Write-Output ("   cmd: " + $cmd)
      }
    }
  } catch {}
}"}

