{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
function BE32($b,$o){ return [BitConverter]::ToUInt32([byte[]]@($b[$o+3],$b[$o+2],$b[$o+1],$b[$o]),0) }
function BE16($b,$o){ return [BitConverter]::ToUInt16([byte[]]@($b[$o+1],$b[$o]),0) }
$bytes = [System.IO.File]::ReadAllBytes('.\workspace\.git\index')
$ver = BE32 $bytes 8
$count = BE32 $bytes 12
Write-Output ("version=" + $ver + " entries=" + $count)
$pos = 16
$targets = @('src/core/handoff/resume-summary.js','src/core/handoff/httpAdapter.js','src/core/handoff/index.js','web/src/margin/SessionDetail.js','web/src/margin/margin.css','test/resumeSummary.test.js','test/marginSessionDetail.test.js','test/marginSurfaceHttpAdapter.test.js','test/handoff.test.js','Margin_Phase0_PoC_Plan.md','task-8-report.md')
$found = @{}
for($i=0; $i -lt $count; $i++){
  $namelen = BE16 $bytes ($pos+60)
  $namelen = $namelen -band 0x0FFF
  $name = [System.Text.Encoding]::UTF8.GetString($bytes, ($pos+62), $namelen)
  $sha = ([System.BitConverter]::ToString($bytes, ($pos+40), 20)) -replace '-',''
  if($targets -contains $name){ $found[$name] = $sha }
  $entryLen = 62 + $namelen
  $entryLen = $entryLen + ((8 - ($entryLen % 8)) % 8)
  $pos += $entryLen
}
foreach($t in $targets){ Write-Output ($t + "  indexsha=" + $found[$t]) }"}

{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$bytes = [System.IO.File]::ReadAllBytes('.\workspace\.git\index')
function BE16x($b,$o){ return [int]$b[$o]*256 + [int]$b[$o+1] }
function BE32x($b,$o){ return [uint32]([int]$b[$o]*16777216 + [int]$b[$o+1]*65536 + [int]$b[$o+2]*256 + [int]$b[$o+3]) }
$ver = BE32x $bytes 4
$cnt = BE32x $bytes 8
Write-Output ("version=" + $ver + " entries=" + $cnt)
$pos = 12
$targets = @('src/core/handoff/resume-summary.js','test/resumeSummary.test.js','test/marginSessionDetail.test.js','task-8-report.md')
$found = @{}
for($i=0; $i -lt $cnt -and $i -lt 2000; $i++){
  if($pos + 62 -gt $bytes.Length){ Write-Output ("bounds break at " + $i); break }
  $flags = BE16x $bytes ($pos+60)
  $namelen = $flags -band 0x0FFF
  $sha = ([System.BitConverter]::ToString($bytes, ($pos+40), 20)) -replace '-',''
  if($namelen -eq 0x0FFF){
    # extended: find NUL terminator
    $end = [System.Array]::IndexOf($bytes, [byte]0, ($pos+62))
    $name = [System.Text.Encoding]::UTF8.GetString($bytes, ($pos+62), ($end-($pos+62)))
    $entryLen = 62 + ($name.Length) + 1
  } else {
    $name = [System.Text.Encoding]::UTF8.GetString($bytes, ($pos+62), $namelen)
    $entryLen = 62 + $namelen
  }
  if($targets -contains $name){ $found[$name] = $sha }
  $pad = (8 - ($entryLen % 8)) % 8
  $pos += $entryLen + $pad
}
foreach($t in $targets){ Write-Output ($t + "  indexsha=" + $found[$t]) }"}

{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
