{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$lines = Get-Content .\input\session.jsonl -Encoding UTF8
foreach($l in $lines){
  try {
    $o = $l | ConvertFrom-Json
    if($o.ordinal -in 69,78,92,113){
      $item = $o.payload.item
      $out = $item.stdout
      Write-Output ("===== ord " + $o.ordinal + " status=" + $item.status + " exit=" + $item.exit_code)
      if($out){
        $m = [regex]::Matches($out, '# (tests|pass|fail|cancelled|skipped|todo) (\d+)')
        $seen=@{}
        foreach($x in $m){ if(-not $seen.ContainsKey($x.Groups[1].Value)){ $seen[$x.Groups[1].Value]=$x.Groups[2].Value } }
        ($seen.GetEnumerator() | ForEach-Object { $_.Key + "=" + $_.Value }) -join '  '
        Write-Output ("")
      }
    }
  } catch {}
}"}
